import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toRoman, fromRoman } from '../roman.js';
test('known', () => { assert.equal(toRoman(1994), 'MCMXCIV'); assert.equal(toRoman(3999), 'MMMCMXCIX'); assert.equal(fromRoman('XLII'), 42); });
test('round trip', () => { for (let i = 1; i < 4000; i++) assert.equal(fromRoman(toRoman(i)), i); });
test('invalid', () => {
  for (const n of [0, 4000, 2.5, -1]) assert.throws(() => toRoman(n), RangeError);
  for (const s of ['IIII', 'VX', 'IC', 'ABC', '', 'MMMM']) assert.throws(() => fromRoman(s), RangeError);
});

solution.roman.js:
const V = [[1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']];
export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) throw new RangeError('out of range');
  let s = '';
  for (const [v, r] of V) while (n >= v) { s += r; n -= v; }
  return s;
}
export function fromRoman(s) {
  if (typeof s !== 'string' || !/^[MDCLXVI]+$/.test(s)) throw new RangeError('not a numeral');
  let n = 0, i = 0;
  for (const [v, r] of V) while (s.startsWith(r, i)) { n += v; i += r.length; }
  if (i !== s.length || n > 3999 || toRoman(n) !== s) throw new RangeError('not canonical');
  return n;
}
